-- ===========================================================================
-- SEED: importa a Tabela TACO (UNICAMP, 597 alimentos) para public.foods
-- como CATALOGO GLOBAL (nutri_id NULL, fonte_dados = TACO). Valores por 100 g.
-- Fonte: github.com/marcelosanto/tabela_taco (TACO.json).
-- Idempotente: apaga os TACO globais e reinsere. Rodar depois do foods_schema.sql.
-- ===========================================================================
delete from public.foods where fonte_dados = 'TACO' and nutri_id is null;


select count(*) as foods_taco from public.foods where fonte_dados = 'TACO';
